"""Gaussian social-learning model used by the four experiments.

Each agent carries candidate precision matrices P, information vectors h, and
log support L. Candidate means are solve(P, h); softmax(L) gives their weights.
The hidden first coordinate means P (phlogiston) or O (oxygen), depending on the
candidate. Only the shared observables C, G, M may be compared or averaged.
"""

from dataclasses import dataclass

import jax

# The figures were generated in double precision with Threefry random keys.
# Set these before creating arrays, rather than depending on machine defaults.
jax.config.update("jax_enable_x64", True)
jax.config.update("jax_default_prng_impl", "threefry2x32")
import jax.numpy as jnp
from jax.scipy.linalg import cho_factor, cho_solve
import numpy as np


@dataclass(frozen=True)
class Config:
    """Reference beliefs and the three mechanisms varied in the paper."""

    P0: jax.Array  # (candidates, coordinates, coordinates)
    h0: jax.Array  # (candidates, coordinates)
    H: jax.Array  # Rows select the measured C, G, M coordinates.
    sigma: float = 1.0  # Observation noise standard deviation.
    omega: float = 0.9  # Retained departure from the fixed reference.
    alpha: float = 0.02  # Amount of model-weight communication.
    fuse: bool = True  # Whether to communicate conditional Gaussian beliefs.


def candidate_priors():
    """Compile the two supplied DAGs, in storage order (hidden, C, G, M).

    CPDs are x = B x + b + noise, with independent residual variances s.
    Therefore P = (I-B).T diag(1/s) (I-B), h = (I-B).T diag(1/s) b.
    The world later supplies fixed signals plus private sensor noise; it does
    not draw a new sample from either candidate DAG on every round.
    """
    B = np.zeros((2, 4, 4))
    B[0, 0, 1], B[0, 2, 1], B[0, 3, 0] = 0.8, 0.8, -0.8
    B[1, 0, 1], B[1, 2, 0], B[1, 3, 0] = 0.8, 0.8, 0.8
    means = np.array([[0., 1., 1., -1.], [0., 1., 1., 1.]])
    b = np.einsum("kij,kj->ki", np.eye(4)[None] - B, means)
    s = jnp.array([0.25, 0.5, 0.5, 0.5])
    precision, information = [], []
    for k in range(2):
        A = jnp.eye(4) - jnp.asarray(B[k])
        AtD = A.T * (1.0 / s)[None, :]
        precision.append(AtD @ A)
        information.append(AtD @ jnp.asarray(b[k]))
    return jnp.stack(precision), jnp.stack(information), jnp.eye(4)[1:]


def gaussian_reference(P, h):
    """Marginalize each hidden variable, then average observable information.

    This is an equal log-linear pool of two marginal Gaussians, not moment
    matching of their mixture. An independent dummy coordinate keeps the same
    observation layout without identifying phlogiston with oxygen.
    """
    P, h = np.asarray(P), np.asarray(h)
    covariance = np.linalg.solve(P, np.broadcast_to(np.eye(4), P.shape))
    means = np.linalg.solve(P, h[..., None])[..., 0]
    marginal = covariance[:, 1:, 1:]
    precision = np.linalg.solve(marginal, np.broadcast_to(np.eye(3), marginal.shape))
    information = np.einsum("kij,kj->ki", precision, means[:, 1:])
    P0, h0 = np.zeros((1, 4, 4)), np.zeros((1, 4))
    P0[0, 0, 0] = 4.0
    P0[0, 1:, 1:] = precision.mean(0)
    h0[0, 1:] = information.mean(0)
    return jnp.asarray(P0), jnp.asarray(h0)


def initial_state(cfg, n, seeds):
    """One identical candidate menu per agent; independent seeded observations."""
    shape = (len(seeds), n)
    return (
        jnp.broadcast_to(cfg.P0, shape + cfg.P0.shape),
        jnp.broadcast_to(cfg.h0, shape + cfg.h0.shape),
        jnp.zeros(shape + (cfg.P0.shape[0],)),
        jnp.stack([jax.random.PRNGKey(int(seed)) for seed in seeds]),
    )


def predictive_score(P, h, H, observation, sigma, attention):
    """Log predictive density before assimilation, with weighted sensor rows.

    Multiplying H and observation by sqrt(attention) matches the weighted
    evidence deposit. A zero-attention channel contributes the same constant
    density to each candidate, so it cannot alter relative model support.
    """
    root = jnp.sqrt(attention)
    H, observation = root[:, None] * H, root * observation
    mean = jnp.linalg.solve(P, h)
    covariance = sigma**2 * jnp.eye(H.shape[0]) + H @ jnp.linalg.solve(P, H.T)
    covariance = 0.5 * (covariance + covariance.T)
    factor = cho_factor(covariance, lower=True)
    residual = observation - H @ mean
    logdet = 2.0 * jnp.log(jnp.diagonal(factor[0])).sum()
    return -0.5 * (H.shape[0] * float(np.log(2 * np.pi)) + logdet
                   + residual @ cho_solve(factor, residual))


def step(state, signal, cfg, W, attention):
    """Communicate, score fresh data, deposit evidence, then retain/anchor.

    Model support: L <- (1-alpha)L + alpha W L + log p(observation | model).
    Beliefs: P <- P0 + omega(P + H.T diag(attention) H / sigma² - P0),
    with the analogous update for h. Communication precedes these updates.
    Log support is accumulated without forgetting; only Gaussian parameters
    relax toward their candidate reference. All displayed arms are ungated.
    """
    P, h, L, key = state
    if cfg.P0.shape[0] > 1:
        L = (1.0 - cfg.alpha) * L + cfg.alpha * (W @ L)
    if cfg.fuse:
        P = jnp.einsum("ij,jkab->ikab", W, P)
        h = jnp.einsum("ij,jkd->ikd", W, h)

    # Each round draws one key per agent, independently of candidate count.
    key, observation_key = jax.random.split(key)
    agent_keys = jax.random.split(observation_key, len(W))

    def observe(Pk, hk, agent_key, weights):
        o = cfg.H @ signal + jax.random.normal(agent_key, (3,)) * cfg.sigma
        scores = jax.vmap(
            lambda p, q: predictive_score(p, q, cfg.H, o, cfg.sigma, weights)
        )(Pk, hk)
        root = jnp.sqrt(jnp.clip(weights, 0.0, None))
        H, weighted_o = root[:, None] * cfg.H, root * o
        inv_var = 1.0 / cfg.sigma**2
        return scores, (H.T @ H) * inv_var, (H.T @ weighted_o) * inv_var

    scores, J, j = jax.vmap(observe)(P, h, agent_keys, attention)
    P = P + J[:, None, :, :]
    h = h + j[:, None, :]
    P = cfg.P0[None] + cfg.omega * (P - cfg.P0[None])
    h = cfg.h0[None] + cfg.omega * (h - cfg.h0[None])
    return P, h, L + scores, key


def rollout(cfg, W, attention, signals, seeds, initial=None):
    """Run a seeded batch and return its checkpoint and post-update readouts.

    Histories contain only oxygen probabilities and observable mixture means.
    The exact checkpoint (including RNG key) allows continuation without new
    randomness. Measurements always draw all three sensor channels, even when
    attention to a channel is zero. Readouts consume no random numbers.
    """
    W, attention, signals = map(jnp.asarray, (W, attention, signals))
    entering = initial_state(cfg, len(W), seeds) if initial is None else initial

    def one(state):
        def update(carry, signal):
            updated = step(carry, signal, cfg, W, attention)
            P, h, L, _ = updated
            q = jax.nn.softmax(L, axis=-1)
            means = jnp.linalg.solve(P, h[..., None])[..., 0][..., 1:]
            mixture = jnp.einsum("nk,nkd->nd", q, means)
            return updated, (q[:, -1], mixture)

        return jax.lax.scan(update, state, signals)

    final, history = jax.jit(jax.vmap(one))(entering)
    oxygen, mixture = (np.asarray(value) for value in history)
    if not np.isfinite(oxygen).all() or not np.isfinite(mixture).all():
        raise FloatingPointError("Non-finite simulation readout")
    return final, {"oxygen": oxygen, "mixture": mixture}
